#!/bin/bash
# ASYMPTOTICS_checks_v1.4 (launcher version 2: engine_asymptotics_table_v9.py, the title naming its script and the root-deficit-proxy line of inbox #14 item 4; launcher version 1 ran version 8; engine spec 32.3 (3): row (3) gains the four stationary-phase (a) lines and the
# 36.25 run's, labelled moot; every kernel label sigma/a = ell/a with sigma^2 = ell^2; obs_j3p_scope_v2's rows marked; row (6) gains the
# version 6 minimum run's table when it lands (printed pending otherwise); inbox #14 item 2: the late window a producer label): version
# 1.3's inputs with the goal file copied fresh and J3' version 7's five runs (version 8's mds; the (a) lines are identical in the version 8
# rebudgets and version 9). Run on the box from engine/. Builder analyst.
cd ${QI2_ROOT}/engine || exit 1
[ -f ASYM/GOAL_lane-alt_v1.4.md ] || { echo "copy the goal file to ASYM/GOAL_lane-alt_v1.4.md first (it lives on the lane host)"; exit 2; }
for f in ../obs/J3v7/J3P_raymap_v8_prod19_max.md ../obs/J3v7/J3P_raymap_v8_prod19_min.md ../obs/J3v7/J3P_raymap_v8_tau4_swingmax.md ../obs/J3v7/J3P_raymap_v8_tau4_max.md ../obs/J3v7/J3P_raymap_v8_tau4_min.md; do [ -f $f ] || { echo "missing $f"; exit 2; }; done
P=${QI2_ROOT}/python
H="the production=H100b/C3prod/collapse_c17_rs64_A_R2_tau8_ell4_avg.json,H100b/C3prod19/collapse_c19_rs64_A_R2_tau8_ell4_avg_r11.json|64|4|8|engine_collapse_v17 then v19;the tau 4 control=H100b/C3prod19/collapse_c19_rs64_A_R2_tau4_ell4_avg.json|64|4|4|engine_collapse_v19;the tau 2 member (to T/rs 21.5)=H100b/C3prod25/collapse_c25_rs64_A_R2_tau2_ell4_avg.json|64|4|2|engine_collapse_v25;the ell 8 record=H100b/C3prod24/collapse_c24_rs64_A_R2_tau8_ell8_avg.json|64|8|8|engine_collapse_v24;the ell 16 record=H100b/C3prod25/collapse_c25_rs64_A_R2_tau8_ell16_avg.json|64|16|8|engine_collapse_v25;the r_s 32 tau 2 member=H100b/C3set24/collapse_c24_rs32_A_R2_tau2_ell4_avg.json|32|4|2|engine_collapse_v24;the r_s 32 tau 1 member=H100b/C3set25/collapse_c25_rs32_A_R2_tau1_ell4_avg.json|32|4|1|engine_collapse_v25"
S="the production (ell 4, tau 8)=J3S/j3p_scope_v2_c19_ell4.json;the tau 4 control (ell 4)=J3S/j3p_scope_v2_c19_tau4.json;the ell 8 record (tau 8)=J3S/j3p_scope_v2_c24_ell8.json"
F="(0.2, 1/4)=Sfam6/star_m0.2_g0.25_ell8.json,Sfam6/star_m0.2_g0.25_ell8_ext.json,Sfam6/star_m0.2_g0.25_ell8_ext2.json;(0.1, 1/4)=Sfam5/star_m0.1_g0.25_ell8.json;(0.05, 1/4)=Sfam7/star_m0.05_g0.25_ell8.json;(0.2, 1/16)=Sfam6/star_m0.2_g0.0625_ell8.json,Sfam6/star_m0.2_g0.0625_ell8_ext.json;(0.1, 1/16)=Sfam6/star_m0.1_g0.0625_ell8.json,Sfam6/star_m0.1_g0.0625_ell8_ext.json;(0.1, 1/64)=Sfam8/star_star8box_m0.1_g0.015625_max.json"
J7="the production at its last maximum (T/rs 35.375)=../obs/J3v7/J3P_raymap_v8_prod19_max.md,the production at its last minimum (T/rs 37.75)=../obs/J3v7/J3P_raymap_v8_prod19_min.md,the tau 4 control at its swing maximum (T/rs 36.25)=../obs/J3v7/J3P_raymap_v8_tau4_swingmax.md,the tau 4 control at T/rs 39.75 (a wiggle at the trough 0.4 percent from the minimum)=../obs/J3v7/J3P_raymap_v8_tau4_max.md,the tau 4 control at its last minimum (T/rs 39.5)=../obs/J3v7/J3P_raymap_v8_tau4_min.md"
CM="C-capture version 6 at the production's last minimum (T/rs 37.75; slice 302)=H100b/CAP/capture_v6_prod19_min.md"
OMP_NUM_THREADS=2 nice -n 10 $P code/engine_asymptotics_table_v9.py --title ASYMPTOTICS_checks_v1.4 --histories "$H" --scope "$S" --jpl ASYM/RESULT_JPL_v1.md --goal ASYM/GOAL_lane-alt_v1.4.md --families "$F" --ovpg3 OVPG3/ovpg3_v1.json --capture H100b/CAP/capture_v6_prod19_last.md --j3p6 "the production=../obs/J3v6/J3P_raymap_v6_prod19.md,the tau 4 control=../obs/J3v6/J3P_raymap_v6_tau4.md,the ell 8 record=../obs/J3v6/J3P_raymap_v6_ell8.md" --j3p7 "$J7" --capture-more "$CM" --md ASYM/ASYMPTOTICS_checks_v1.4_t9.md > ASYM/log_v9.log 2>&1
echo "exit $?"
